entries[43675] = { ["name"] = "Fandral Staghelm's Silver Coin", ["text"] = "Binds when picked up\n\"The War of the Shifting Sands... I wish I could forget it ever happened.\"\nSell Price:" }
entries[43676] = { ["name"] = "Arcanist Doan's Silver Coin", ["text"] = "Binds when picked up\n\"Oh, why won't you notice me? Abbendis, I would follow you anywhere. I wish you would notice me...\"\nSell Price:" }
entries[43677] = { ["name"] = "High Tinker Mekkatorque's Silver Coin", ["text"] = "Binds when picked up\n\"How does this fountain even work? I wonder if I could make one.\"\nSell Price:" }
entries[43678] = { ["name"] = "Antonidas' Silver Coin", ["text"] = "Binds when picked up\n\"Grant me the strength to accept the things that I cannot change, the courage to change the things I can and the wisdom to know the difference.\"\nSell Price:" }
entries[43679] = { ["name"] = "Muradin Bronzebeard's Silver Coin", ["text"] = "Binds when picked up\n\"May the Holy Light protect us on our expedition to the frozen north.\"\nSell Price:" }
entries[43680] = { ["name"] = "King Varian Wrynn's Silver Coin", ["text"] = "Binds when picked up\n\"I wish the uprising back at home would settle itself soon. I wouldn't want anyone to be hurt.\"\nSell Price:" }
entries[43681] = { ["name"] = "King Terenas Menethil's Silver Coin", ["text"] = "Binds when picked up\n\"May my son Arthas always act in the best interest of his people.\"\nSell Price:" }
entries[43682] = { ["name"] = "King Anasterian Sunstrider's Silver Coin", ["text"] = "Binds when picked up\n\"I hope young Kael'thas realizes that one day he must lead our people.\"\nSell Price:" }
entries[43683] = { ["name"] = "Khadgar's Silver Coin", ["text"] = "Binds when picked up\n\"Turalyon and Alleria, wherever you are, may you be well.\"\nSell Price:" }
entries[43684] = { ["name"] = "Medivh's Silver Coin", ["text"] = "Binds when picked up\n\" \"\nSell Price:" }
entries[43685] = { ["name"] = "Maiev Shadowsong's Silver Coin", ["text"] = "Binds when picked up\n\"Where's Illidan?\"\nSell Price:" }
entries[43686] = { ["name"] = "Alleria's Silver Coin", ["text"] = "Binds when picked up\n\"May my sisters realize their full potential, the name Windrunner known as result of their deeds.\"\nSell Price:" }
entries[43687] = { ["name"] = "Aegwynn's Silver Coin", ["text"] = "Binds when picked up\n\"I really wish you mages would get your heads out from inside your own... books.\"\nSell Price:" }
