entries[43697] = { ["name"] = "Artifact from the Nathrezim Homeworld", ["text"] = "Quest Item\nUnique\n\"What strange construction. It must be one of the most alien-looking objects you've ever seen.\"" }
entries[43698] = { ["name"] = "Giant Sewer Rat", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss a Giant Sewer Rat\nRequires level 1 to 80 ( 80)\nSell Price:" }
entries[43699] = { ["name"] = "The Curse of Flesh Disc", ["text"] = "Quest Item\nUnique\n\"There's information on this thing? What? There's no writing!\"" }
entries[43701] = { ["name"] = "A Footman's Copper Coin", ["text"] = "Binds when picked up\n\"Wish I had that cousin of mine's duty to do nothing more than lug wood around carelessly...\"\nSell Price:" }
entries[43702] = { ["name"] = "Alonsus Faol's Copper Coin", ["text"] = "Binds when picked up\n\"One day, I hope to spread the path of the Light to the common people and teach them the value of the Three Virtues.\"\nSell Price:" }
entries[43703] = { ["name"] = "Ansirem's Copper Coin", ["text"] = "Binds when picked up\n\"I wish for happiness and acceptance for my daughter. She feels so out of place here...\"\nSell Price:" }
entries[43704] = { ["name"] = "Attumen's Copper Coin", ["text"] = "Binds when picked up\n\"Can I have a more comfortable saddle? My hindquarters ache.\"\nSell Price:" }
entries[43705] = { ["name"] = "Danath's Copper Coin", ["text"] = "Binds when picked up\n\"I hope a troll dies, right... NOW.\"\nSell Price:" }
entries[43706] = { ["name"] = "Dornaa's Shiny Copper Coin", ["text"] = "Binds when picked up\n\"I wish that that jerk Arthas would fall into a pile of magnataur doody!\"\nSell Price:" }
entries[43707] = { ["name"] = "Eitrigg's Copper Coin", ["text"] = "Binds when picked up\n\"May Tirion's quest here in Northrend end with success, or may he die honorably in battle.\"\nSell Price:" }
entries[43708] = { ["name"] = "Elling Trias' Copper Coin", ["text"] = "Binds when picked up\n\"Being a rogue is hard work. Someday I hope to pursue my life's one true passion...\"\nSell Price:" }
entries[43709] = { ["name"] = "Falstad Wildhammer's Copper Coin", ["text"] = "Binds when picked up\n\"I hope I end up in another book eventually.\"\nSell Price:" }
entries[43710] = { ["name"] = "Genn's Copper Coin", ["text"] = "Binds when picked up\n\"Pah, the fountains in Gilneas could grant ten times as many wishes as Dalaran's!\"\nSell Price:" }
entries[43711] = { ["name"] = "Inigo's Copper Coin", ["text"] = "Binds when picked up\n\"I wish I had my father back...\"\nSell Price:" }
entries[43712] = { ["name"] = "Krasus' Copper Coin", ["text"] = "Binds when picked up\n\"My prayers go out to my brothers and sisters who still suffer in the heart of Grim Batol. I WILL free them.\"\nSell Price:" }
entries[43713] = { ["name"] = "Kryll's Copper Coin", ["text"] = "Binds when picked up\n\"Boom. Now boom? I wish for a boom. Boom go! This coin must be broken, I wonder if it'll explode.\"\nSell Price:" }
entries[43714] = { ["name"] = "Landro Longshot's Copper Coin", ["text"] = "Binds when picked up\n\"I wish I'd kept that coin...\"\nSell Price:" }
entries[43715] = { ["name"] = "Molok's Copper Coin", ["text"] = "Binds when picked up\n\"Just once -- that's all I ask for, just once -- let the lass ride with me...\"\nSell Price:" }
entries[43716] = { ["name"] = "Murky's Copper Coin", ["text"] = "Binds when picked up\n\"I wish the water in Northrend wasn't so cold, it makes me sleepy.\"\nSell Price:" }
entries[43717] = { ["name"] = "Princess Calia Menethil's Copper Coin", ["text"] = "Binds when picked up\n\"I hope that handsome nobleman Lord Prestor notices me! He's so dreamy!\"\nSell Price:" }
entries[43718] = { ["name"] = "Private Marcus Jonathan's Copper Coin", ["text"] = "Binds when picked up\n\"I wish to grow a glorious, bushy mustache someday.\"\nSell Price:" }
entries[43719] = { ["name"] = "Salandria's Shiny Copper Coin", ["text"] = "Binds when picked up\n\"Someday, I'm gonna be more powerful than all of these mages!\"\nSell Price:" }
entries[43720] = { ["name"] = "Squire Rowe's Copper Coin", ["text"] = "Binds when picked up\n\"I hope I can get transferred out of Stormwind eventually and see Cersei again. Nothing good ever happens in this city.\"\nSell Price:" }
entries[43721] = { ["name"] = "Stalvan's Copper Coin", ["text"] = "Binds when picked up\n\"You mages refuse to provide me that which hastens the inevitable fate of two people in love, when only one is too naive to see it. I wish you all ruin.\"\nSell Price:" }
entries[43722] = { ["name"] = "Vereesa's Copper Coin", ["text"] = "Binds when picked up\n\"Asto're da shan're. Turus Fulo Il'amare, A'Talah Adore. Isera'duna...\"\nSell Price:" }
entries[43723] = { ["name"] = "Vargoth's Copper Coin", ["text"] = "Binds when picked up\n\"I wish Captain Sanders would hurry up with my shipment of wine.\"\nSell Price:" }
entries[43724] = { ["name"] = "Celestial Ruby Ring", ["text"] = "Quest Item\nUnique\n\"Ring? It's more like a necklace and a heavy one at that!\"" }
