entries[43951] = { ["name"] = "Reins of the Bronze Drake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Lost time is never found again. Oh, never mind I found it. -Chronormu\"\nDrop:\nInfinite Corruptor\nZone:\nThe Culling of Stratholme" }
entries[43952] = { ["name"] = "Reins of the Azure Drake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Always speak politely to an enraged dragon.\"\nDrop:\nAlexstrasza's Gift\nLocation:\nEye of Eternity" }
entries[43953] = { ["name"] = "Reins of the Blue Drake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Come not between the dragon and his wrath.\"\nDrop:\nAlexstrasza's Gift\nLocation:\nEye of Eternity" }
entries[43954] = { ["name"] = "Reins of the Twilight Drake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"But the most important rule, the rule you can never forget, no matter how much he cries, no matter how much he begs, never feed him after midnight.\"\nDrop:\nSartharion\nLocation:\nThe Obsidian Sanctum" }
entries[43955] = { ["name"] = "Reins of the Red Drake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires The Wyrmrest Accord\n- Exalted\n\n\"You should never listen to minstrels' fancies. A dragon would never hurt a soul, unless they tried to hurt him first.\"\nVendor:\nCielstrasza\nZone:\nDragonblight\nFaction:\nThe Wyrmrest Accord - Exalted\nCost:" }
entries[43956] = { ["name"] = "Reins of the Black War Mammoth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Normally placid beasts, these intelligent animals form a strong bond with their riders, making them loyal and fearless in battle.\"\nVendor:\nKnight Dameron\nZone:\nWintergrasp\nCost:\n15" }
entries[43958] = { ["name"] = "Reins of the Ice Mammoth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires The Sons of Hodir\n- Revered\nSell Price:\n\"Many ice giants claim that they have trained their favored white mammoths to trigger avalanches with their trumpeting calls.\"\nVendor:\nLillehoff\nZone:\nThe Storm Peaks\nFaction:\nThe Sons of Hodir - Revered\nCost:" }
entries[43959] = { ["name"] = "Reins of the Grand Black War Mammoth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this three-person mount.\nCalls forth the Grand Black War Mammoth! Allows two passengers to board that are in the same group as the driver.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Once used by giants to carry heavily armored warriors, these grand war mammoths can easily bear more than one rider of less-than-giant stature.\"\nDrop:\nBoss Drop\nLocation:\nVault of Archavon" }
entries[43961] = { ["name"] = "Reins of the Grand Ice Mammoth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this three-person mount.\nCalls forth the Grand Ice Mammoth! Allows two passengers to board that are in the same group as the driver.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires The Sons of Hodir\n- Exalted\nSell Price:\n\"Due to high winds and avalanches, the Sons of Hodir recommend bringing at least two companions if venturing into the dangerous Storm Peaks.\"\nVendor:\nLillehoff\nZone:\nThe Storm Peaks\nFaction:\nThe Sons of Hodir - Exalted\nCost:" }
entries[43962] = { ["name"] = "Reins of the White Polar Bear", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The frost vrykul believe that wearing a necklace of polar bear claws will grant them otherworldly strength.\"\nDrop:\nHyldnir Spoils\nLocation:\nThe Storm Peaks" }
