entries[43964] = { ["name"] = "Reins of the Black Polar Bear", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The taunka use black polar bear pelts in their religious rites, usually at the funerals of those who hunt black polar bears.\"\nLegacy" }
